// Retry delay: seconds to wait for a 429, from its Retry-After header (seconds or an HTTP date).
// At least 60 seconds; no upper cap, because the provider asked for that wait.
const value = String($input.first().json.headers?.['retry-after'] ?? '').trim();
const seconds = /^\d+$/.test(value) ? Number(value) : Math.ceil((Date.parse(value) - Date.now()) / 1000);
return [{ json: { seconds: Number.isFinite(seconds) ? Math.max(60, seconds) : 60 } }];

// Parse and filter: read the free-for-dev README and the LowEndBox items, keep offers not seen before, update the watcher's counters and emit Discord items (kind offer or alert).
// Seen links live in static data (seen: link -> first-seen ISO time). On the first run everything parsed is recorded and nothing is emitted.
// The real free-for-dev headings of the server and hosting sections (checked 2026-10-24).
const WANTED_HEADINGS = ['Major Cloud Providers', 'IaaS', 'PaaS', 'Web Hosting'];
const FREE_PATTERN = /\bfree\b|\$0(?![\d.])|always free|free tier/i;
const NEGATED_PATTERN = /\b(?:no|not|without)\s+(?:\w+\s+)?free\b/gi; // 'No free tier' is a paid post
const SEEN_DAYS = 180;
const LIST_LIMIT = 10;
const DAY_MS = 86400000;
const STALE_MS = 12 * 3600000; // two schedule intervals (6 hours each)
const SEEN_LIMIT = 5000;

// Local calendar day (YYYY-MM-DD) in the given time zone.
function localDay(now, timeZone) {
  return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
}

// Bullet lines under the wanted '##' headings. Returns the offers and how many wanted headings were found.
function parseReadme(markdown) {
  const offers = [];
  let heading = '';
  let sections = 0;
  for (const line of String(markdown ?? '').split('\n')) {
    const title = line.match(/^##\s+(.+?)\s*$/);
    if (title) {
      heading = title[1];
      if (WANTED_HEADINGS.includes(heading)) sections += 1;
      continue;
    }
    const bullet = line.match(/^\s*[*-]\s+\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)\s*(?:[—–-]\s*)?(.*)$/);
    if (bullet && WANTED_HEADINGS.includes(heading)) {
      offers.push({ name: bullet[1], url: bullet[2], source: 'free-for-dev', summary: bullet[3] });
    }
  }
  return { offers, sections };
}

// The retry's response when the retry ran, otherwise the first response. A node that did not run throws; that means undefined.
function fromNode(name) {
  try {
    return $(name).first().json;
  } catch {
    return undefined;
  }
}

const readme = fromNode('Retry free-for-dev') ?? fromNode('Fetch free-for-dev') ?? {};
const readmeOk = readme.statusCode >= 200 && readme.statusCode < 300;
// n8n puts a full text response in `data` (`body` is kept for a JSON response).
const readmeParsed = readmeOk ? parseReadme(readme.data ?? readme.body) : { offers: [], sections: 0 };

// LowEndBox items come from Fetch LowEndBox; a failed feed arrives as one item with an error field.
const feedItems = $input.all().map((item) => item.json);
const feedError = feedItems.some((item) => item.error);
const posts = feedItems.filter((item) => item.link && !item.error);
const freePosts = posts.filter((post) =>
  [post.title, post.contentSnippet ?? post.content ?? post.description].some((text) => FREE_PATTERN.test(String(text ?? '').replace(NEGATED_PATTERN, ' '))));
const lowendboxOffers = freePosts.map((post) => ({ name: post.title, url: post.link, source: 'LowEndBox', summary: '' }));
const offers = [...readmeParsed.offers, ...lowendboxOffers];

const now = new Date();
const stamp = now.toISOString();
const data = $getWorkflowStaticData('global');
const today = localDay(now, $env.GENERIC_TIMEZONE || 'UTC');
const old = data.metrics ?? {};
// A new local day starts with no alerts sent yet. The 09:00 summary resets the counters, not this; last successes carry over.
const day = old.day === today ? old : { ...old, day: today, alerted: {} };
const counters = { ...day.counters };
const count = (name, n = 1) => {
  counters[name] = (counters[name] ?? 0) + n;
};
const lastSuccessAt = { ...day.lastSuccessAt };
const alerted = { ...day.alerted };
const alerts = [];
// Each alert key is sent at most once per local day.
function alertOnce(key, title, body) {
  if (alerted[key]) return;
  alerted[key] = true;
  alerts.push({ kind: 'alert', title, body, url: '' });
}

// Seen links: the first run records everything and emits nothing. Entries older than SEEN_DAYS are dropped.
const firstRun = data.seen === undefined;
const cutoff = now.getTime() - SEEN_DAYS * DAY_MS;
const seen = Object.fromEntries(Object.entries(data.seen ?? {}).filter(([, first]) => Date.parse(first) >= cutoff));
const fresh = [];
let skipped = 0;
for (const offer of offers) {
  if (seen[offer.url]) {
    skipped += 1;
    continue;
  }
  seen[offer.url] = stamp;
  if (!firstRun) fresh.push(offer);
}

count('runs');
count('new_offers', fresh.length);
count('skipped_seen', skipped);
count('filtered_out', posts.length - freePosts.length);
counters.fetched = { 'free-for-dev': readmeParsed.offers.length, lowendbox: posts.length };
if (!readmeOk) count('errors');
if (feedError) count('errors');
if (readmeOk) lastSuccessAt['free-for-dev'] = stamp;
if (posts.length && !feedError) lastSuccessAt.lowendbox = stamp;

if (!readmeOk) {
  alertOnce('fetch:free-for-dev', 'Feed failed: free-for-dev', `HTTP ${readme.statusCode ?? 'no response'} from the free-for-dev README. Next try in 6 hours.`);
} else if (readmeParsed.offers.length === 0) {
  alertOnce('parse:free-for-dev', 'No offers parsed: free-for-dev', `Found ${readmeParsed.sections} of ${WANTED_HEADINGS.length} wanted sections. The README format may have changed.`);
}
if (feedError || posts.length === 0) {
  alertOnce('fetch:lowendbox', 'Feed failed or empty: LowEndBox', 'The LowEndBox feed returned an error or no posts.');
}

// A source with no successful read for two schedule intervals is stale.
for (const source of ['free-for-dev', 'lowendbox']) {
  const last = lastSuccessAt[source];
  if (!last || now.getTime() - Date.parse(last) > STALE_MS) {
    alertOnce(`stale:${source}`, `Stale source: ${source}`, `${last ? `No successful read since ${last}.` : 'No successful read on record.'} Two schedule intervals (12 hours) have passed.`);
  }
}
if (Object.keys(seen).length > SEEN_LIMIT) {
  alertOnce('seen:size', 'Seen list is large', `${Object.keys(seen).length} entries (limit ${SEEN_LIMIT}). Check the 180-day cutoff.`);
}
data.metrics = { day: today, counters, lastSuccessAt, alerted };
if (!firstRun || offers.length > 0) data.seen = seen;

const messages = [];
if (fresh.length) {
  const shown = fresh.slice(0, LIST_LIMIT);
  const lines = shown.map((offer) => `• ${offer.name} (${offer.source}): ${offer.url}`);
  if (fresh.length > shown.length) lines.push(`and ${fresh.length - shown.length} more`);
  messages.push({ kind: 'offer', title: `${fresh.length} new free offer${fresh.length === 1 ? '' : 's'}`, body: lines.join('\n'), url: '' });
}
return [...messages, ...alerts].map((json) => ({ json }));

// Shape summary: build the 09:00 summary line from the counters, then reset the counters for the new local day.
const today = new Intl.DateTimeFormat('en-CA', { timeZone: $env.GENERIC_TIMEZONE || 'UTC', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const data = $getWorkflowStaticData('global');
const metrics = data.metrics ?? {};
const counters = metrics.counters ?? {};
const lastSuccessAt = metrics.lastSuccessAt ?? {};
const line = `Watch offers · ${counters.runs ?? 0} runs · ${counters.new_offers ?? 0} new · ${counters.skipped_seen ?? 0} already seen · ${counters.filtered_out ?? 0} filtered out · ${counters.errors ?? 0} fetch errors`;
const sources = ['free-for-dev', 'lowendbox'].map((name) => `${name}: ${lastSuccessAt[name] ? `last ok ${lastSuccessAt[name]}` : 'no successful read yet'}`);
data.metrics = { day: today, counters: {}, lastSuccessAt, alerted: metrics.alerted ?? {} };
return [{ json: { kind: 'summary', title: `Watch offers summary (${metrics.day ?? today})`, body: [line, ...sources].join('\n'), url: '' } }];
